#!/usr/bin/env python3
"""API-8: generate apps/web/lib/api/client.ts from the backend OpenAPI schema.

Stdlib only. The backend app is imported in-process (no server, no network,
no MODEL_API_KEY), so every TypeScript type below is derived from the live
FastAPI contract and never hand-typed. CI regenerates and fails on drift.
"""

from __future__ import annotations

import json
import os
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "apps" / "web" / "lib" / "api" / "client.ts"
HEADER = (
    "// GENERATED by scripts/gen_api_client.py from backend OpenAPI. Do not edit.\n"
    "// Regenerate with: python3 scripts/gen_api_client.py\n"
)

IDENT = re.compile(r"^[A-Za-z_$][A-Za-z0-9_$]*$")


def _import_app() -> object:
    """Import the FastAPI app, re-exec'ing into backend/.venv when deps are not on PATH."""
    sys.path.insert(0, str(ROOT / "backend"))
    try:
        import fastapi  # noqa: F401
    except ModuleNotFoundError:
        venv = ROOT / "backend" / ".venv" / "bin" / "python"
        if not venv.exists() or os.environ.get("SHOWME_REEXEC"):
            sys.exit("backend deps missing: run `uv sync --project backend` first")
        os.environ["SHOWME_REEXEC"] = "1"
        os.execv(str(venv), [str(venv), str(Path(__file__).resolve()), *sys.argv[1:]])
    from showme.api.main import app

    return app


def _literal(value: object) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    if value is None:
        return "null"
    return json.dumps(value)


def _ref_name(ref: str) -> str:
    return ref.rsplit("/", 1)[-1]


def ts_type(schema: object) -> str:
    """Map one OpenAPI schema node to a TypeScript type. Unknown shapes become `unknown`."""
    if not isinstance(schema, dict):
        return "unknown"
    if "$ref" in schema:
        return _ref_name(str(schema["$ref"]))
    for key in ("anyOf", "oneOf"):
        branches = schema.get(key)
        if isinstance(branches, list):
            parts: list[str] = []
            for branch in branches:
                part = ts_type(branch)
                if part not in parts:
                    parts.append(part)
            return " | ".join(parts) if parts else "unknown"
    if "enum" in schema and isinstance(schema["enum"], list):
        return " | ".join(dict.fromkeys(_literal(v) for v in schema["enum"]))
    if "const" in schema:
        return _literal(schema["const"])

    kind = schema.get("type")
    if isinstance(kind, list):
        return " | ".join(dict.fromkeys(ts_type({**schema, "type": k}) for k in kind))
    if kind == "array":
        item = ts_type(schema.get("items"))
        return item + "[]" if IDENT.match(item) or item in {"string", "number", "boolean"} else f"Array<{item}>"
    if kind == "object" or "properties" in schema:
        props = schema.get("properties")
        if not isinstance(props, dict) or not props:
            extra = schema.get("additionalProperties")
            return f"Record<string, {ts_type(extra)}>" if isinstance(extra, dict) else "Record<string, unknown>"
        required = schema.get("required") if isinstance(schema.get("required"), list) else []
        members = []
        for name, sub in props.items():
            key = name if IDENT.match(name) else json.dumps(name)
            opt = "" if name in required else "?"
            members.append(f"{key}{opt}: {ts_type(sub)};")
        return "{ " + " ".join(members) + " }"
    return {"integer": "number", "number": "number", "string": "string", "boolean": "boolean", "null": "null"}.get(
        str(kind), "unknown"
    )


def emit_types(spec: dict) -> str:
    schemas = spec["components"]["schemas"]
    blocks: list[str] = []
    for name in sorted(schemas):
        schema = schemas[name]
        props = schema.get("properties") if isinstance(schema, dict) else None
        if isinstance(props, dict) and props and schema.get("type", "object") == "object":
            required = schema.get("required") if isinstance(schema.get("required"), list) else []
            lines = [f"export interface {name} {{"]
            for prop, sub in props.items():
                key = prop if IDENT.match(prop) else json.dumps(prop)
                opt = "" if prop in required else "?"
                lines.append(f"  {key}{opt}: {ts_type(sub)};")
            lines.append("}")
            blocks.append("\n".join(lines))
        else:
            blocks.append(f"export type {name} = {ts_type(schema)};")
    return "\n\n".join(blocks)


def emit_paths(spec: dict) -> str:
    paths = spec["paths"]
    for route in ("/v1/step", "/v1/refine", "/v1/guides", "/v1/guides/{token}"):
        if route not in paths:
            sys.exit(f"OpenAPI is missing {route}: backend contract changed, update the client wrapper")
    return (
        "// Next rewrites /api/* to the backend (next.config.mjs); paths come from the OpenAPI spec.\n"
        "export const API_PATHS = {\n"
        '  step: "/api/v1/step",\n'
        '  refine: "/api/v1/refine",\n'
        '  guides: "/api/v1/guides",\n'
        "} as const;"
    )


WRAPPER = """
/** Typed error body per ARCH §4: {error: {code, message, retry_after_s?}}. */
export class ApiClientError extends Error {
  readonly code: string;
  readonly retryAfterS: number | undefined;

  constructor(code: string, message: string, retryAfterS?: number) {
    super(message);
    this.name = "ApiClientError";
    this.code = code;
    this.retryAfterS = retryAfterS;
  }
}

export type RequestOptions = { signal?: AbortSignal };
export type StepOptions = RequestOptions & {
  locale?: string;
  escalate?: boolean;
};

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function toApiError(status: number, body: unknown): ApiClientError {
  if (isRecord(body) && isRecord(body.error)) {
    const { code, message, retry_after_s: retryAfterS } = body.error;
    if (typeof code === "string" && typeof message === "string") {
      return new ApiClientError(
        code,
        message,
        typeof retryAfterS === "number" ? retryAfterS : undefined,
      );
    }
  }
  return new ApiClientError(
    `http_${status}`,
    "The request failed. Please try again.",
  );
}

async function post<T>(
  path: string,
  payload: unknown,
  signal?: AbortSignal,
): Promise<T> {
  const response = await fetch(path, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
    signal,
  });
  const body: unknown = await response.json().catch(() => null);
  if (response.status !== 200) throw toApiError(response.status, body);
  // shortcut: transport payload is cast, not validated at runtime; add a
  // schema validator if the response models start carrying unions.
  return body as T;
}

/** PRIV-1: the only image the API accepts is one produced by redact(). */
function imagePayload(
  image: RedactedImage,
): Pick<StepRequest, "image" | "image_meta"> {
  return {
    image: image.dataUrl,
    image_meta: {
      width: image.meta.width,
      height: image.meta.height,
      redaction: {
        auto_regions: image.meta.autoRegions,
        manual_regions: image.meta.manualRegions,
        pipeline: image.meta.pipeline,
      },
    },
  };
}

export async function step(
  image: RedactedImage,
  goal: string,
  history: HistoryItem[],
  opts: StepOptions = {},
): Promise<StepResponse> {
  const payload: StepRequest = {
    ...imagePayload(image),
    goal,
    history,
    locale: opts.locale ?? "en-GB",
    escalate: opts.escalate ?? false,
  };
  return post<StepResponse>(API_PATHS.step, payload, opts.signal);
}

export async function refine(
  image: RedactedImage,
  box: BoxPx,
  point: PointPx,
  opts: RequestOptions = {},
): Promise<RefineResponse> {
  const payload: RefineRequest = { ...imagePayload(image), box, point };
  return post<RefineResponse>(API_PATHS.refine, payload, opts.signal);
}

export type GuideStepInput = {
  n: number;
  instruction: string;
  image: RedactedImage;
  target: Target | null;
  svgPath: string | null;
  svgOrigin: PointPx | null;
};

/** PRIV-5: only redacted trail images (from redact()) can be shared, and only with consent. */
export async function createGuide(
  goal: string,
  steps: GuideStepInput[],
  consent: boolean,
  opts: RequestOptions = {},
): Promise<CreateGuideResponse> {
  const payload: CreateGuideRequest = {
    goal,
    consent,
    steps: steps.map((s) => ({
      n: s.n,
      instruction: s.instruction,
      image: s.image.dataUrl,
      target: s.target,
      svg_path: s.svgPath,
      svg_origin: s.svgOrigin,
      width: s.image.meta.width,
      height: s.image.meta.height,
    })),
  };
  return post<CreateGuideResponse>(API_PATHS.guides, payload, opts.signal);
}

export async function deleteGuide(token: string, deleteKey: string, opts: RequestOptions = {}): Promise<void> {
  const response = await fetch(`${API_PATHS.guides}/${encodeURIComponent(token)}`, {
    method: "DELETE",
    headers: { "X-Delete-Key": deleteKey },
    signal: opts.signal,
  });
  const body: unknown = await response.json().catch(() => null);
  if (response.status !== 200) throw toApiError(response.status, body);
}
"""


def main() -> None:
    # Creating the app only reads settings defaults; it never calls the model API.
    os.environ.setdefault("MODEL_API_KEY", "unused-openapi-generation")
    spec: dict = _import_app().openapi()  # type: ignore[attr-defined]
    text = f"{HEADER}\nimport type {{ RedactedImage }} from \"../redaction/redact\";\n\n"
    text += emit_types(spec) + "\n\n" + emit_paths(spec) + "\n" + WRAPPER
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(text, encoding="utf-8")
    print(f"wrote {OUT.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
